// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Layers".

First, there is a pattern layer which is then repeated three
times and bent into a tunnel shape.
*/

const scale = Math.max(1, devicePixelRatio)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2820269/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
  createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
  resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;

#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
#define MN min(R.x,R.y)
#define MX max(R.x,R.y)
#define SE(v,s) S(s+1./MN,s-1./MN,v)
#define palette(a) (.5+.5*cos(6.3*((a)+vec3(0,.1,.2))))
#define reveal(p) SE(MN/MX*length(p),sqrt(S(1.,.0,1./T)))

vec3 aces(vec3 p) {
  p=max(p*.6,.0);
  float
  a=2.51,
  b=0.03,
  c=2.43,
  d=0.59,
  e=0.14;
  return clamp((p*(a*p+b))/(p*(c*p+d)+e),.0,1.);
}

vec2 layer(vec2 p, vec2 off, float zoom, float a) {
	float s=sin(a), c=cos(a);
	mat2 m=mat2(c,-s,s,c);
	return (p-off)*m*zoom;
}

void main() {
	vec2 uv=(FC-.5*R)/MN, p=uv;
	vec3 col=vec3(0);

	// form a tunnel (comment out to see the pattern)
	p=vec2(.5/length(p),atan(p.x,p.y)*2./6.28318);	

	// add layer upon layer 
	const float n=3.;
	for (float i=.0; i++<n;) {
		float k=i+1.;
		vec2 q=layer(p,vec2(-.1*k*T,sin(T*.1)),k,.0);
		q=fract(q*vec2(1,.25))-.5;

		float d=max(abs(q.x),abs(q.y));
		d=sin(12.*d+T*.2);
		d=abs(d);
		col+=SE(d,.5)*palette(length(q)+T*.125+k)/k*S(.0,1.5,.5+.5*(n-i));
	}

	// post processing
	col=mix(vec3(0),col,pow(S(.0,.3,length(uv)),2.));
	col=aces(col);
	col=sqrt(col);

	// reveal effect
	col*=reveal(uv);

	// vignette
	vec2 c=FC/R;
	c*=1.-c.yx;
	float vig=c.x*c.y*25.;
	vig=pow(vig,.5);
	col*=vig;

	O=vec4(col,1);
}

